<?php
/** Disposable local checks for required customer identity, scope and privacy exports. */
use CrystalTap\{Auth,DB,Customer,Conversations,Privacy,Settings,Fault};
if(!defined('WP_CLI')||!WP_CLI)exit;
if(home_url()!=='http://localhost:8080')throw new RuntimeException('Customer fixtures require the local development site.');
global $wpdb;$prefix=$wpdb->prefix.'ctai_customer_test_'.bin2hex(random_bytes(4)).'_';add_filter('ctai_table_prefix',static fn()=>$prefix);
$schema=get_option('ctai_schema');$savedSettings=get_option('ctai_settings',null);$cookie=$_COOKIE[Auth::COOKIE]??null;$users=[];$result=0;$GLOBALS['customer_checks']=0;
function ccheck(bool $value,string $name):void{if(!$value)throw new RuntimeException('FAIL: '.$name);$GLOBALS['customer_checks']++;echo "PASS: $name\n";}
function cdeny(callable $f,string $name):void{try{$f();}catch(Fault $e){ccheck($e->status===400,$name);return;}throw new RuntimeException('Expected rejection: '.$name);}
function creq(string $method,string $path,array $body=[],string $csrf=''):WP_REST_Response{$r=new WP_REST_Request($method,'/crystaltap-ai/v1'.$path);if($method!=='GET'){$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($body));$r->set_header('X-CTAI-CSRF',$csrf);}return rest_do_request($r);}
function csession():array{$token=bin2hex(random_bytes(32));$_COOKIE[Auth::COOKIE]=$token;$csrf=hash_hmac('sha256',$token,wp_salt('nonce'));$id=DB::insert('sessions',['token_hash'=>hash('sha256',$token),'csrf_hash'=>hash('sha256',$csrf),'expires_at'=>gmdate('Y-m-d H:i:s',time()+3600),'created_at'=>DB::now()]);return [$id,$csrf,$token];}
try{
 DB::migrate();
 update_option('ctai_settings',['welcome'=>'Hello po! How can we help you today?','width'=>380,'height'=>580],false);$upgraded=Settings::get();ccheck(str_contains($upgraded['welcome'],'{name}')&&$upgraded['width']===480&&$upgraded['height']===740,'stock welcome and compact dimensions upgrade to named greeting and larger window');
 Settings::save(['welcome'=>'Hello {name}, our team is here.','width'=>420,'height'=>700,'ai_enabled'=>false]);$custom=Settings::get();ccheck($custom['welcome']==='Hello {name}, our team is here.'&&$custom['width']===420&&$custom['height']===700,'custom greeting and dimensions are preserved');
 Settings::save(['width'=>380,'height'=>580]);ccheck(Settings::get()['width']===380&&Settings::get()['height']===580,'explicit compact dimensions remain configurable after the upgrade');
 Settings::save(['welcome'=>'  ']);ccheck(trim(Settings::publicConfig()['welcome'])!==''&&Settings::publicConfig()['ai_enabled']===false,'blank welcome falls back to a real template and public configuration declares AI mode');
 foreach(['agent','other','supervisor']as$name){$users[$name]=wp_insert_user(['user_login'=>'ctai_customer_'.$name.'_'.bin2hex(random_bytes(4)),'user_pass'=>wp_generate_password(32),'role'=>$name==='supervisor'?'ctai_supervisor':'ctai_agent']);}
 [$session,$csrf,$token]=csession();$legacy=Conversations::start($session);
 $wpdb->query('ALTER TABLE '.DB::table('conversations').' DROP COLUMN customer_name, DROP COLUMN customer_email, DROP COLUMN customer_phone');DB::migrate();$old=Conversations::get((int)$legacy['id']);ccheck($old['customer_name']===''&&Customer::details($old)===null,'upgrade preserves older conversations with empty profile defaults');
 wp_set_current_user(0);$missing=creq('POST','/public/conversations',[],$csrf);ccheck($missing->get_status()===400&&$missing->get_data()['code']==='customer_name_required','public API requires a name before a new conversation');
 $named=creq('POST','/public/conversations',['name'=>'  Maria <b>Reyes</b>  '],$csrf);ccheck($named->get_status()===200,'name-only chat succeeds with optional email and phone omitted');$namedRow=Conversations::get((int)$named->get_data()['id']);ccheck($namedRow['customer_name']==='Maria Reyes'&&$namedRow['customer_email']===''&&$namedRow['customer_phone']==='','profile trims markup and stores optional fields as empty');
 cdeny(fn()=>Customer::validate(['name'=>'  ']),'whitespace-only names are rejected');cdeny(fn()=>Customer::validate(['name'=>['invalid']]),'non-string profile values are rejected');cdeny(fn()=>Customer::validate(['name'=>str_repeat('a',191)]),'overlong names are rejected');cdeny(fn()=>Customer::validate(['name'=>'Maria','email'=>'invalid-email']),'optional email must be valid when provided');cdeny(fn()=>Customer::validate(['name'=>'Maria','phone'=>'---']),'optional phone must contain a real number');
 $silent=Conversations::customer((int)$namedRow['id'],'Human-only support fixture','human-only-fixture-1234');$history=Conversations::history((int)$namedRow['id']);ccheck($silent['conversation']['status']==='waiting'&&count(array_filter($history,fn($m)=>$m['sender']==='system'))===0,'AI-disabled chat hands off silently without a support-update message');
 $input=['name'=>'Alex Santos','email'=>'customer-profile@example.invalid','phone'=>'+63 900 000 0000'];$full=creq('POST','/public/conversations',$input,$csrf);ccheck($full->get_status()===200,'new chat saves all three supplied contact fields');$id=(int)$full->get_data()['id'];
 $resume=creq('GET','/public/session')->get_data();ccheck($resume['customer']['name']===$input['name']&&$resume['customer']['email']===$input['email'],'same visitor can resume their own saved contact details');
 csession();$other=creq('GET','/public/session')->get_data();ccheck($other['customer']===null&&$other['conversations']===[],'another visitor does not receive the customer profile');$_COOKIE[Auth::COOKIE]=$token;
 $c=Conversations::handoff($id);wp_set_current_user($users['agent']);$inbox=Conversations::inbox('waiting');$entry=array_values(array_filter($inbox,fn($row)=>(int)$row['id']===$id))[0];ccheck(!isset($entry['customer'])&&!str_contains(wp_json_encode($entry),$input['email']),'unclaimed queue does not disclose name, email or phone');ccheck(creq('GET','/agent/conversations/'.$id)->get_status()===403,'unassigned agent cannot read contact details');
 $c=Conversations::action($id,'claim',(int)$c['version']);$details=creq('GET','/agent/conversations/'.$id)->get_data()['customer'];ccheck(array_intersect_key($details,$input)===$input,'assigned agent receives name, email and phone in the conversation view');
 wp_update_user(['ID'=>$users['agent'],'display_name'=>'Alex Support']);DB::insert('agent_profiles',['user_id'=>$users['agent'],'availability'=>'online','heartbeat'=>DB::now()]);$live=creq('GET','/public/conversations/'.$id.'/messages')->get_data();ccheck($live['agent']===['name'=>'Alex Support','online'=>true]&&$live['customer']['name']==='Alex Santos','visitor receives current support name and fresh presence with the right customer');
 $wpdb->update(DB::table('agent_profiles'),['heartbeat'=>gmdate('Y-m-d H:i:s',time()-180)],['user_id'=>$users['agent']]);ccheck(creq('GET','/public/conversations/'.$id.'/messages')->get_data()['agent']['online']===false,'stale agent heartbeat does not pretend the agent is online');
 $found=Conversations::inbox('mine',1,'Alex Santos');ccheck(count($found)===1&&$found[0]['customer']['name']==='Alex Santos','authorized inbox can search the new customer name');
 wp_set_current_user($users['other']);ccheck(creq('GET','/agent/conversations/'.$id)->get_status()===403,'another agent cannot read a claimed customer profile');
 wp_set_current_user($users['supervisor']);ccheck(creq('GET','/agent/conversations/'.$id)->get_data()['customer']['phone']===$input['phone'],'supervisor can see contact fields with existing access rules');
 wp_update_user(['ID'=>$users['other'],'display_name'=>'Jamie Support']);$c=Conversations::action($id,'transfer',(int)$c['version'],$users['other']);$transferred=creq('GET','/public/conversations/'.$id.'/messages')->get_data();ccheck($transferred['agent']['name']==='Jamie Support','public support identity updates after transfer');
 wp_update_user(['ID'=>$users['other'],'display_name'=>'staff-private@example.invalid']);ccheck(Conversations::publicAgent(Conversations::get($id))['name']==='Support team','staff email used as display name is not exposed to visitors');
 $export=Privacy::exportEmail($input['email']);ccheck(count($export['data'])===1&&str_contains(wp_json_encode($export),$input['phone']),'WordPress privacy export includes profiles without a lead record');
 $erase=Privacy::eraseEmail($input['email']);ccheck($erase['items_removed']&&!$wpdb->get_var($wpdb->prepare('SELECT id FROM '.DB::table('conversations').' WHERE id=%d',$id)),'WordPress privacy erasure removes profile-only conversations');
 echo "\n".$GLOBALS['customer_checks']." customer profile checks passed. No external provider called.\n";
}catch(Throwable $e){echo $e->getMessage()."\n";$result=1;}finally{require_once ABSPATH.'wp-admin/includes/user.php';foreach($users as$user)wp_delete_user($user);foreach($wpdb->get_col($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($prefix).'%'))as$t)$wpdb->query('DROP TABLE `'.$t.'`');remove_all_filters('ctai_table_prefix');update_option('ctai_schema',$schema,false);if($savedSettings===null)delete_option('ctai_settings');else update_option('ctai_settings',$savedSettings,false);if($cookie===null)unset($_COOKIE[Auth::COOKIE]);else $_COOKIE[Auth::COOKIE]=$cookie;}
if($result)WP_CLI::halt($result);
